600	    private Mono<List<MailboxRenamedResult>> renameSubscriptionsIfNeeded(List<MailboxRenamedResult> renamedResults,
601	                                                                   RenameOption option, MailboxSession fromSession, MailboxSession toSession) {
602	        if (option == RenameOption.RENAME_SUBSCRIPTIONS) {
603	            SubscriptionMapper subscriptionMapper = mailboxSessionMapperFactory.getSubscriptionMapper(fromSession);
604	
605	            return subscriptionMapper.findSubscriptionsForUserReactive(fromSession.getUser())
606	                .collectList()
607	                .flatMap(subscriptions -> Flux.fromIterable(renamedResults)
608	                    .concatMap(renamedResult -> {
609	                        Function<Subscription, Mono<Void>> renameFunction = subscription -> subscriptionMapper.deleteReactive(subscription)
610	                            .then(subscriptionMapper.saveReactive(new Subscription(toSession.getUser(), renamedResult.getDestinationPath().asEscapedString())));
611	                        Subscription legacySubscription = new Subscription(fromSession.getUser(), renamedResult.getOriginPath().getName());
612	                        if (subscriptions.contains(legacySubscription)) {
613	                            return renameFunction.apply(legacySubscription);
614	                        }
615	                        Subscription subscription = new Subscription(fromSession.getUser(), renamedResult.getOriginPath().asEscapedString());
616	                        if (subscriptions.contains(subscription)) {
617	                            return renameFunction.apply(subscription);
618	                        }
619	                        return Mono.empty();
620	                    })
621	                    .then()
622	                    .thenReturn(renamedResults));
623	        }
624	        return Mono.just(renamedResults);
625	    }
