701	    private Publisher<Void> renameSubMailboxes(MailboxPath newMailboxPath, MailboxSession toSession, MailboxMapper mapper,
702	                                               MailboxPath from, MailboxQuery.UserBound query, ImmutableList.Builder<MailboxRenamedResult> resultBuilder) {
703	        if (DefaultMailboxes.INBOX.equalsIgnoreCase(from.getName())) {
704	            return Mono.empty();
705	        }
706	        return locker.executeReactiveWithLockReactive(from, mapper.findMailboxWithPathLike(query)
707	            .concatMap(sub -> {
708	                String subOriginalName = sub.getName();
709	                String subNewName = newMailboxPath.getName() + subOriginalName.substring(from.getName().length());
710	                MailboxPath fromPath = new MailboxPath(from, subOriginalName);
711	                sub.setName(subNewName);
712	                sub.setUser(toSession.getUser());
713	                return mapper.rename(sub)
714	                    .map(mailboxId -> {
715	                        resultBuilder.add(new MailboxRenamedResult(sub.getMailboxId(), fromPath, sub.generateAssociatedPath()));
716	                        return mailboxId;
717	                    })
718	                    .retryWhen(Retry.backoff(5, Duration.ofMillis(10)))
719	                    .then(Mono.fromRunnable(() -> LOGGER.debug("Rename mailbox sub-mailbox {} to {}", subOriginalName, subNewName)));
720	            }, LOW_CONCURRENCY)
721	            .then(), MailboxPathLocker.LockType.Write);
722	    }
