    void renameShouldThrowInsufficientWhenToDoesNotBelongToUser() throws Exception {
        MailboxSession s1 = mailboxManager.createSystemSession(USER_1);
        MailboxPath p1 = MailboxPath.forUser(USER_1, "mbx1");
        MailboxPath p2 = MailboxPath.forUser(USER_2, "mbx2");
        mailboxManager.createMailbox(p1, s1);
        assertThatThrownBy(() -> mailboxManager.renameMailbox(p1, p2, s1))
            .isInstanceOf(InsufficientRightsException.class);
    }

    @Test
    void renameByIdShouldSucceedWhenDestParentHasCreateRight() throws Exception {
        MailboxSession s1 = mailboxManager.createSystemSession(USER_1);
        MailboxSession s2 = mailboxManager.createSystemSession(USER_2);
        MailboxPath original = MailboxPath.forUser(USER_1, "mbx1");
        MailboxPath shared = MailboxPath.forUser(USER_2, "shared");
        MailboxId id = mailboxManager.createMailbox(original, s1).get();
        mailboxManager.createMailbox(shared, s2);
        mailboxManager.setRights(shared, MailboxACL.EMPTY.apply(MailboxACL.command()
