        List<MailboxRenamedResult> r = mailboxManager.renameMailbox(childId, dest, s1);
        assertThat(r).hasSize(1);
        assertThat(r.get(0).getDestinationPath()).isEqualTo(dest);
        assertThat(r.get(0).getOriginPath()).isEqualTo(child);
    }
